'use dom'
import type { ForwardedRef, ReactElement, ReactNode } from 'react'
import { forwardRef } from 'react'

// prop types

type IconData = string | ReactNode

type IconSize =
	| 'large'
	| 'medium'
	| 'small'
	| 'xs'
	| 'custom'
	| 'xl'
	| 'xxl'
	| 'xxs'
	| 'xxxl'

type IconProps = {
	size?: IconSize
	content: IconData
	viewBoxHeight?: number
	viewBoxWidth?: number
}

// config

const DEFAULT_PROPS = {
	size: 'medium',
	viewBoxWidth: 18,
	viewBoxHeight: 18
} as const

// main

function IconComponent(
	props: IconProps,
	ref: ForwardedRef<SVGSVGElement>
): ReactElement {
	const p = { ...DEFAULT_PROPS, ...props }

	return (
		<div>
			<svg
				ref={ref}
				className={`shrink-0 fill-current ${
					p.size === 'xxxl'
						? 'h-[48px] w-[48px]'
						: p.size === 'xxl'
						? 'h-[36px] w-[36px]'
						: p.size === 'xl'
						? 'h-[30px] w-[30px]'
						: p.size === 'large'
						? 'h-[24px] w-[24px]'
						: p.size === 'medium'
						? 'h-[18px] w-[18px]'
						: p.size === 'small'
						? 'h-[16px] w-[16px]'
						: p.size === 'xs'
						? 'h-[13px] w-[13px]'
						: p.size === 'xxs'
						? 'h-[8px] w-[8px]'
						: ''
				}`}
				viewBox={`0 0 ${p.viewBoxWidth} ${p.viewBoxHeight}`}
				xmlns="http://www.w3.org/2000/svg"
			>
				{typeof p.content === 'string' ? (
					// SVG path
					<path d={p.content} fillRule="evenodd" clipRule="evenodd" />
				) : (
					// react elements
					p.content
				)}
			</svg>
		</div>
	)
}

const Icon = forwardRef<SVGSVGElement, IconProps>(IconComponent)

export default Icon
